INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5885086, 854088, 83313, '<td valign="top">the nitpicker in me is tempted to call this overprocessed, but the strong greens really work for this scene. It''s not overprocessed if it suits.</td>', 'the nitpicker in me is tempted to call this overprocessed, but the strong greens really work for this scene. It''s not overprocessed if it suits.', '2010-03-01 13:20:35.000000', NULL, 1),
(5885092, 856393, 83313, '<td valign="top">I like what you did with it. The close in crop works well. (No vote, comment only.)</td>', 'I like what you did with it. The close in crop works well. (No vote, comment only.)', '2010-03-01 13:22:19.000000', NULL, 1),
(5885096, 857504, 83313, '<td valign="top">I like the effort to try and do a semi-abstract view of this plane, but this is coming off to me fairly soft and slightly OOF. Might be just a few quick adjustments away from being a really nice shot, however.</td>', 'I like the effort to try and do a semi-abstract view of this plane, but this is coming off to me fairly soft and slightly OOF. Might be just a few quick adjustments away from being a really nice shot, however.', '2010-03-01 13:24:15.000000', NULL, 1),
