(5886854, 857400, 34659, '<td valign="top">Stunning...  Is this your daughter Judi?  Beautiful portrait.  Love the makeup, hair, &amp; lighting.  Very well done.</td>', 'Stunning...  Is this your daughter Judi?  Beautiful portrait.  Love the makeup, hair, & lighting.  Very well done.', '2010-03-02 13:30:32.000000', NULL, 1),
(5886855, 854431, 34659, '<td valign="top">Absolutely wonderful!  Great energy, emotion, and perfect tones.  Beautiful.</td>', 'Absolutely wonderful!  Great energy, emotion, and perfect tones.  Beautiful.', '2010-03-02 13:30:57.000000', NULL, 1),
(5886857, 855191, 34659, '<td valign="top">WOW!  Love this!  It looks like I could reach out and touch it.  Well done on the PP.</td>', 'WOW!  Love this!  It looks like I could reach out and touch it.  Well done on the PP.', '2010-03-02 13:31:22.000000', NULL, 1),
