(5886868, 857173, 34659, '<td valign="top">WOW!  Incredible make-up job and VERY cool setup.  Beautifully done.</td>', 'WOW!  Incredible make-up job and VERY cool setup.  Beautifully done.', '2010-03-02 13:35:24.000000', NULL, 1),
(5886870, 855462, 34659, '<td valign="top">Where the **** is this?  Is the figure a cutout?  The colors and detail are awesome.  Great comp too.  Can''t wait to find out more about this intriguing shot.  VERY cool!</td>', 'Where the **** is this?  Is the figure a cutout?  The colors and detail are awesome.  Great comp too.  Can''t wait to find out more about this intriguing shot.  VERY cool!', '2010-03-02 13:37:45.000000', NULL, 1),
