(5888269, 856809, 65234, '<td valign="top">Great detail and nice light on him.</td>', 'Great detail and nice light on him.', '2010-03-03 09:27:28.000000', NULL, 1),
(5888273, 856936, 65234, '<td valign="top">Those eyes are rather unnerving.  Between that and the DOF making the child''s head look sort of disembodied the image feels downright evil!</td>', 'Those eyes are rather unnerving.  Between that and the DOF making the child''s head look sort of disembodied the image feels downright evil!', '2010-03-03 09:30:04.000000', NULL, 1),
(5888277, 857223, 104841, '<td valign="top">Nice composition be carful with the stitching as it is noticeable here, maybe a longer shutter to really smooth out the water. Try shooting a little bit earlier in the evening so you get a more colourful and interesting sky.</td>', 'Nice composition be carful with the stitching as it is noticeable here, maybe a longer shutter to really smooth out the water. Try shooting a little bit earlier in the evening so you get a more colourful and interesting sky.', '2010-03-03 09:32:20.000000', NULL, 1),
(5888284, 856731, 65234, '<td valign="top">Looks vaguely like a Mourning Dove up there and the White-throated Sparrow doesn''t look too concerned.  Like your composition and processing; tells a story quite well.</td>', 'Looks vaguely like a Mourning Dove up there and the White-throated Sparrow doesn''t look too concerned.  Like your composition and processing; tells a story quite well.', '2010-03-03 09:38:43.000000', NULL, 1),
