(5889623, 857115, 70503, '<td valign="top">The color of the water is so blue. I like that contrast against the snow. Nice job!</td>', 'The color of the water is so blue. I like that contrast against the snow. Nice job!', '2010-03-03 22:56:21.000000', NULL, 1),
(5889627, 851471, 70503, '<td valign="top">Oh how I love elephants. My favorite creatures in the world! I love their poses... so sweet. I think the background light is a bit harsh on the elephants. Not my taste, but it is a really cool shot.</td>', 'Oh how I love elephants. My favorite creatures in the world! I love their poses... so sweet. I think the background light is a bit harsh on the elephants. Not my taste, but it is a really cool shot.', '2010-03-03 23:01:08.000000', NULL, 1),
(5889629, 852658, 70503, '<td valign="top">Nicely done. Nice colors and texture. Like the faded out background.</td>', 'Nicely done. Nice colors and texture. Like the faded out background.', '2010-03-03 23:01:53.000000', NULL, 1),
(5889632, 856028, 70503, '<td valign="top">this is pretty slick! It feels like the Seagull is on top of my screen (very 3D). I lie the subtle colors of the water and fish with the vibrant seagull.</td>', 'this is pretty slick! It feels like the Seagull is on top of my screen (very 3D). I lie the subtle colors of the water and fish with the vibrant seagull.', '2010-03-03 23:03:21.000000', NULL, 1),
(5889634, 855844, 70503, '<td valign="top">very nicely shot. Makes me think of Escher or Dali. I love love love the light and shadows. Very well done!</td>', 'very nicely shot. Makes me think of Escher or Dali. I love love love the light and shadows. Very well done!', '2010-03-03 23:04:23.000000', NULL, 1),
(5889635, 857134, 70503, '<td valign="top">Very nice clear shot of a flying bird. Love the wingspan!</td>', 'Very nice clear shot of a flying bird. Love the wingspan!', '2010-03-03 23:04:54.000000', NULL, 1),
(5889641, 856936, 70503, '<td valign="top">The EYES are gorgeous! It feels like a Hardy Boy''s Mystery book. Nice shadows.</td>', 'The EYES are gorgeous! It feels like a Hardy Boy''s Mystery book. Nice shadows.', '2010-03-03 23:07:34.000000', NULL, 1),
(5889655, 857662, 70503, '<td valign="top">Very sexy. I like the subtle colors with the black and white.</td>', 'Very sexy. I like the subtle colors with the black and white.', '2010-03-03 23:19:42.000000', NULL, 1),
