(5889789, 857643, 92027, '<td valign="top">Great moment and title fits nicely :)</td>', 'Great moment and title fits nicely :)', '2010-03-04 04:01:08.000000', NULL, 1),
(5889794, 857181, 104841, '<td valign="top">nice dynamic shot. I think that you have tried to fit in everything whereas perhaps it would be a stronger image if you got closer to the kids. I also don''t know about the colour of the mono conversion</td>', 'nice dynamic shot. I think that you have tried to fit in everything whereas perhaps it would be a stronger image if you got closer to the kids. I also don''t know about the colour of the mono conversion', '2010-03-04 04:50:14.000000', NULL, 1),
