INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5891639, 856809, 98339, '<td valign="top">excellent detail in the feathers and the total picture...really well done</td>', 'excellent detail in the feathers and the total picture...really well done', '2010-03-05 14:57:10.000000', NULL, 1),
(5891651, 857370, 30982, '<td valign="top">I do quite like this - wonderful sense of adventure that is created not only by the cool architecture but by the people - they''re all positioned just "so" to give it that adventure/awe kinda feel.  Much warmer and more real than just a picture of a building.  Serendipity is a good thing!</td>', 'I do quite like this - wonderful sense of adventure that is created not only by the cool architecture but by the people - they''re all positioned just "so" to give it that adventure/awe kinda feel.  Much warmer and more real than just a picture of a building.  Serendipity is a good thing!', '2010-03-05 15:13:38.000000', NULL, 1),
(5891665, 857665, 73942, '<td valign="top">love the desat, this is really pretty</td>', 'love the desat, this is really pretty', '2010-03-05 15:37:56.000000', NULL, 1),
(5891684, 857542, 54446, '<td valign="top">Hey, very nice Bobcat.  In case someone confuses this with a Lynx, it''s definitely a Bobcat.  The tail is black above, but not below. If it was a Lynx, it would be a black tail end, including below.  A Lynx would have more pronounced ear tufts, and longer, grayer fur without indistinct spotting.  I love your narrow DOF and the natural setting on the edge of a harvested corn field.  Great job!  10</td>', 'Hey, very nice Bobcat.  In case someone confuses this with a Lynx, it''s definitely a Bobcat.  The tail is black above, but not below. If it was a Lynx, it would be a black tail end, including below.  A Lynx would have more pronounced ear tufts, and longer, grayer fur without indistinct spotting.  I love your narrow DOF and the natural setting on the edge of a harvested corn field.  Great job!  10', '2010-03-05 15:51:02.000000', NULL, 1),
(5891685, 855022, 98339, '<td valign="top">I think you used a noise filter on this and I really like it</td>', 'I think you used a noise filter on this and I really like it', '2010-03-05 15:55:04.000000', NULL, 1),
