(5893614, 857486, 65234, '<td valign="top">I like this!  That sparkles of light and bit of rainbow colors is a neat contrast to the window.</td>', 'I like this!  That sparkles of light and bit of rainbow colors is a neat contrast to the window.', '2010-03-07 17:35:02.000000', NULL, 1),
(5893615, 857026, 65234, '<td valign="top">Not turkeys ... maybe I need to lower my feeders ;-)</td>', 'Not turkeys ... maybe I need to lower my feeders ;-)', '2010-03-07 17:36:38.000000', NULL, 1),
