(5893618, 857382, 65234, '<td valign="top">Ooh, a Pileated!  I love seeing those guys.  Looks like this one was far away (typical) and you had to crop a lot ... ended up kind of speckly.</td>', 'Ooh, a Pileated!  I love seeing those guys.  Looks like this one was far away (typical) and you had to crop a lot ... ended up kind of speckly.', '2010-03-07 17:38:33.000000', NULL, 1),
(5893619, 856802, 65234, '<td valign="top">I love those colors and shadows!</td>', 'I love those colors and shadows!', '2010-03-07 17:39:18.000000', NULL, 1),
(5893624, 854593, 65234, '<td valign="top">Hope you were using a long lens!!</td>', 'Hope you were using a long lens!!', '2010-03-07 17:43:58.000000', NULL, 1),
(5893627, 853901, 65234, '<td valign="top">LOL!  I love that the gull is the only one looking at the camera ;-)</td>', 'LOL!  I love that the gull is the only one looking at the camera ;-)', '2010-03-07 17:46:36.000000', NULL, 1),
(5893629, 855243, 65234, '<td valign="top">Nice detail on the ducks.</td>', 'Nice detail on the ducks.', '2010-03-07 17:48:32.000000', NULL, 1),
