(5893634, 857118, 65234, '<td valign="top">Love these little guys; they are so photogenic!  Like the light, DOF and the soft green background.</td>', 'Love these little guys; they are so photogenic!  Like the light, DOF and the soft green background.', '2010-03-07 17:51:13.000000', NULL, 1),
(5893636, 852650, 65234, '<td valign="top">Marvelous DOF and light.</td>', 'Marvelous DOF and light.', '2010-03-07 17:51:18.000000', NULL, 1),
(5893637, 856940, 65234, '<td valign="top">Gorgeous, gorgeous light!</td>', 'Gorgeous, gorgeous light!', '2010-03-07 17:51:21.000000', NULL, 1),
(5893638, 855455, 65234, '<td valign="top">What a fun image!  It is a wonder they don''t knock each other out of the air.</td>', 'What a fun image!  It is a wonder they don''t knock each other out of the air.', '2010-03-07 17:51:24.000000', NULL, 1),
(5893639, 857049, 65234, '<td valign="top">Fabulous light!  What a fascinating scene to explore :-)</td>', 'Fabulous light!  What a fascinating scene to explore :-)', '2010-03-07 17:51:27.000000', NULL, 1),
(5893640, 857254, 65234, '<td valign="top">Nice colors and tones.</td>', 'Nice colors and tones.', '2010-03-07 17:51:30.000000', NULL, 1),
(5893641, 856393, 65234, '<td valign="top">Great detail.</td>', 'Great detail.', '2010-03-07 17:51:33.000000', NULL, 1),
(5893642, 856926, 65234, '<td valign="top">Like the perspective.  Looks tonemapped, in a way that I think complements the subject.  Reminds me of an architect''s drawing of a proposed structure.</td>', 'Like the perspective.  Looks tonemapped, in a way that I think complements the subject.  Reminds me of an architect''s drawing of a proposed structure.', '2010-03-07 17:51:39.000000', NULL, 1),
(5893643, 857378, 65234, '<td valign="top">Geez, look at the wingspan on that thing!  Fabulous detail and I like the shadowy light.  Suits a hunter.</td>', 'Geez, look at the wingspan on that thing!  Fabulous detail and I like the shadowy light.  Suits a hunter.', '2010-03-07 17:51:42.000000', NULL, 1),
(5893644, 852004, 65234, '<td valign="top">There could be so many stories to explain this one.  Just enough detail to set my imagination going, and yet it feels intimate.  Well done.</td>', 'There could be so many stories to explain this one.  Just enough detail to set my imagination going, and yet it feels intimate.  Well done.', '2010-03-07 17:51:44.000000', NULL, 1),
(5893645, 855005, 65234, '<td valign="top">Nice; I can almost feel the mist.  Like the light here.</td>', 'Nice; I can almost feel the mist.  Like the light here.', '2010-03-07 17:51:47.000000', NULL, 1),
(5893646, 855654, 65234, '<td valign="top">Lovely exposure on the sun and perfect perspective to make it look like it''s perched atop the tree.</td>', 'Lovely exposure on the sun and perfect perspective to make it look like it''s perched atop the tree.', '2010-03-07 17:51:49.000000', NULL, 1),
(5893647, 856884, 65234, '<td valign="top">Nice tones and light.</td>', 'Nice tones and light.', '2010-03-07 17:51:54.000000', NULL, 1),
(5893648, 854431, 65234, '<td valign="top">Gotta'' love the outfit :-)  The pose just screams "carefree!"</td>', 'Gotta'' love the outfit :-)  The pose just screams "carefree!"', '2010-03-07 17:52:01.000000', NULL, 1),
(5893649, 857532, 65234, '<td valign="top">I feel like I could reach out and touch him!</td>', 'I feel like I could reach out and touch him!', '2010-03-07 17:52:04.000000', NULL, 1),
(5893651, 857667, 65234, '<td valign="top">LOL!  Certainly tells a story ;-)</td>', 'LOL!  Certainly tells a story ;-)', '2010-03-07 17:52:22.000000', NULL, 1),
(5893652, 857476, 65234, '<td valign="top">Lovely environmental sort of portrait.  The bird (Little Blue Heron?) stands out nicely against the background.</td>', 'Lovely environmental sort of portrait.  The bird (Little Blue Heron?) stands out nicely against the background.', '2010-03-07 17:52:24.000000', NULL, 1),
(5893654, 856500, 65234, '<td valign="top">I don''t want to like this ... it''s a drop shot.  The drops are well done (and more complicated than anything I could ever achieve, I suspect) but what really attracted me is the light on the mug and the background.  I really like that and the red/brown tones.</td>', 'I don''t want to like this ... it''s a drop shot.  The drops are well done (and more complicated than anything I could ever achieve, I suspect) but what really attracted me is the light on the mug and the background.  I really like that and the red/brown tones.', '2010-03-07 17:54:40.000000', NULL, 1),
(5893655, 857670, 65234, '<td valign="top">Pretty light.</td>', 'Pretty light.', '2010-03-07 17:54:44.000000', NULL, 1),
(5893656, 857641, 65234, '<td valign="top">Like the composition here, and the shadows.</td>', 'Like the composition here, and the shadows.', '2010-03-07 17:55:01.000000', NULL, 1),
(5893657, 856671, 65234, '<td valign="top">Fun motion blur :-)  Lots of nice detail in the architecture.</td>', 'Fun motion blur :-)  Lots of nice detail in the architecture.', '2010-03-07 17:55:06.000000', NULL, 1),
(5893659, 857554, 65234, '<td valign="top">Oooh, nice tones and lines!  Love the light to dark progression.</td>', 'Oooh, nice tones and lines!  Love the light to dark progression.', '2010-03-07 17:55:23.000000', NULL, 1),
(5893660, 856227, 65234, '<td valign="top">Very nicely done!  Love the rays of light from the sun and the palpable sense of movement of the water into the abyss.</td>', 'Very nicely done!  Love the rays of light from the sun and the palpable sense of movement of the water into the abyss.', '2010-03-07 17:55:31.000000', NULL, 1),
(5893661, 856739, 65234, '<td valign="top">Really like this abstract!  <i>Feels</i> like crashing surf.</td>', 'Really like this abstract!  Feels like crashing surf.', '2010-03-07 17:55:37.000000', NULL, 1),
(5893662, 857445, 65234, '<td valign="top">Gorgeous detail and nice framing.  Love the eye contact.</td>', 'Gorgeous detail and nice framing.  Love the eye contact.', '2010-03-07 17:55:45.000000', NULL, 1);
